// scripts/audit_param_coverage.ts
var OD_ADDrs = [42, 44, 45, 46, 47, 49, 50, 51, 53, 54, 55, 56];
var DIST_ADDRS = [57, 59, 60, 61, 62, 64, 65, 66, 68, 69, 70, 71];
var AMP_ADDRS = [74, 75, 76, 77, 79, 80, 81, 83, 84, 85, 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 239];
function audit(moduleId, tbl, segAddrs) {
  const mod = MODULES.find((m) => m.id === moduleId);
  const subs = mod ? getMergedSubModels(mod) : [];
  const seen = /* @__PURE__ */ new Set();
  const missing = [];
  const segBad = [];
  let nPos = 0;
  for (const sm of subs) {
    for (const cap of sm.captures ?? []) {
      nPos++;
      const key = `${sm.name}/${cap.pos}`;
      seen.add(key);
      const rec = tbl[key];
      if (!rec) {
        missing.push(`${sm.display || sm.name} \xB7 ${cap.pos}  \u2192  ${key}`);
        continue;
      }
      if (segAddrs) {
        const regs = rec.allRegs ?? rec;
        const absent = segAddrs.filter((a) => regs[a] === void 0);
        if (absent.length) segBad.push(`${key} \u7F3A\u6BB5 ${absent.join(",")}`);
      } else if (Array.isArray(rec) && rec.length !== 35) {
        segBad.push(`${key} \u6BB5\u6570=${rec.length}(\u5E94 35)`);
      }
    }
  }
  const orphans = Object.keys(tbl).filter((k) => !seen.has(k));
  return { moduleId, nModel: subs.length, nPos, missing, orphans, segBad };
}
var results = [
  audit("overdrive", OVERDRIVE_DEFAULTS, OD_ADDrs),
  audit("dist", OVERDRIVE_DEFAULTS, DIST_ADDRS),
  audit("amp-head", AMP_DEFAULTS2, AMP_ADDRS),
  audit("cabinet", CABINET_PEQ)
];
for (const r of results) {
  console.log(`
\u2550\u2550\u2550 ${r.moduleId} \u2550\u2550\u2550`);
  console.log(`\u578B\u53F7 ${r.nModel} / \u4F4D\u7F6E ${r.nPos} | \u4F4D\u7F6E\u7A7A\u7F3A ${r.missing.length} | \u5B64\u513F\u952E ${r.orphans.length} | \u6BB5\u5F02\u5E38 ${r.segBad.length}`);
  if (r.missing.length) console.log("  \u7A7A\u7F3A:\n    " + r.missing.slice(0, 12).join("\n    ") + (r.missing.length > 12 ? `
    ...+${r.missing.length - 12}` : ""));
  if (r.segBad.length) console.log("  \u6BB5\u5F02\u5E38:\n    " + r.segBad.slice(0, 8).join("\n    ") + (r.segBad.length > 8 ? `
    ...+${r.segBad.length - 8}` : ""));
  if (r.orphans.length) console.log("  \u5B64\u513F\u952E(\u524D10): " + r.orphans.slice(0, 10).join(" | ") + (r.orphans.length > 10 ? ` ...+${r.orphans.length - 10}` : ""));
}
console.log("\n\u2550\u2550\u2550 SERIES_REGISTRY \u578B\u53F7\u952E \u2550\u2550\u2550");
var serMissing = 0;
var serOrphanModel = [];
for (const fam of SERIES_REGISTRY) {
  for (const mm of fam.models) {
    if (!OVERDRIVE_DEFAULTS[mm.key]) {
      serMissing++;
      console.log(`  \u7F3A\u5931: ${fam.moduleId}/${fam.uiName}/${mm.label} \u2192 ${mm.key}`);
    }
  }
}
var allModelKeys = new Set(SERIES_REGISTRY.flatMap((f) => f.models.map((m) => m.key)));
for (const k of Object.keys(OVERDRIVE_DEFAULTS)) {
  if (!allModelKeys.has(k)) serOrphanModel.push(k);
}
console.log(`\u578B\u53F7\u952E\u7F3A\u5931 ${serMissing} | \u6570\u636E\u8868\u4E2D\u975E\u578B\u53F7\u952E ${serOrphanModel.length}`);
console.log("  \u975E\u578B\u53F7\u952E\u6837\u4F8B(\u524D8): " + serOrphanModel.slice(0, 8).join(" | "));
